import React, { useEffect, useRef, useState } from "react";
import {
  Chart,
  BarElement,
  CategoryScale,
  LinearScale,
  Legend
} from "chart.js";

Chart.register(BarElement, CategoryScale, LinearScale, Legend);

const DATA_PATH = "/pokemon_data/";

export default function GenStats() {
    const chartRef = useRef(null);
    const canvasRef = useRef(null);
    const [selectedGens, setSelectedGens] = useState(["1"]);

    const loadCSV = async (file) => {
        const res = await fetch(file);
        return await res.text();
    };

    const parseCSV = (data) =>
        data.split("\n").slice(1).map(row => row.split(","));

    const calculateAverages = (data) => {
        let totals = [0,0,0,0,0,0];
        let count = 0;

        data.forEach(row => {
            if (row.length < 11) return;

            for (let i = 0; i < 6; i++) {
                totals[i] += parseInt(row[i+5]);
            }
            count++;
        });

        return totals.map(val => val / count);
    };

    useEffect(() => {
        const updateChart = async () => {
            const datasets = [];

            for (let gen of selectedGens) {
                const csv = await loadCSV(`${DATA_PATH}pokemon_gen_${gen}.csv`);
                const parsed = parseCSV(csv);
                const avg = calculateAverages(parsed);

                datasets.push({
                    label: `Gen ${gen}`,
                    data: avg,
                    backgroundColor: `hsl(${gen * 40}, 70%, 60%)`
                });
            }

            if (chartRef.current) {
                chartRef.current.destroy();
            }

            const ctx = canvasRef.current.getContext("2d");

            chartRef.current = new Chart(ctx, {
                type: "bar",
                data: {
                    labels: ['HP','Attack','Defense','SpAtk','SpDef','Speed'],
                    datasets
                },
                options: {
                    responsive: true,
                    animation: { duration: 800 }
                }
            });
        };

        updateChart();
    }, [selectedGens]);

    const toggleGen = (gen) => {
        setSelectedGens(prev =>
            prev.includes(gen)
                ? prev.filter(g => g !== gen)
                : [...prev, gen]
        );
    };

    return (
        <div>
            <h2>Pokémon Average Base Stats by Generation</h2>

            {Array.from({ length: 9 }, (_, i) => i + 1).map(gen => (
                <label key={gen} style={{ marginRight: "10px" }}>
                    <input
                        type="checkbox"
                        checked={selectedGens.includes(String(gen))}
                        onChange={() => toggleGen(String(gen))}
                    />
                    Gen {gen}
                </label>
            ))}

            <br /><br />
            <canvas ref={canvasRef}></canvas>
        </div>
    );
}
